from textlesson import build
S=dict(cls=7,subj="science",subj_file="science")
build(dict(S,ch="changes-around-us-physical-and-chemical",topic="physical-and-chemical-changes",name_en="Physical and chemical changes",name_ta="இயற்பியல், வேதியியல் மாற்றங்கள்",
 objectives=["Tell physical changes from chemical changes","Give daily-life examples of each"],
 story=("Ice and iron","Priya left an ice cube in the sun and it became water. Her bicycle left out in the rain got a brown coating of rust.\n\"Ice can become ice again,\" said her brother, \"but rust never turns back into shining iron.\""),
 explain=["In a physical change the shape, size, state or appearance changes but no new substance forms, and it can often be reversed. Melting ice, cutting paper, dissolving sugar and boiling water are physical changes.","In a chemical change a new substance with new properties forms and the change is usually not easy to reverse. Rusting of iron, burning of paper, curdling of milk and cooking food are chemical changes.","Signs of chemical change are a change in colour, a gas given off, a change in temperature, a smell, or a new solid forming."],
 terms=["physical change","chemical change","rusting","reversible"],
 narr=[("In a physical change no new substance forms. Melting ice and dissolving sugar are physical changes.","physical change"),("In a chemical change a new substance forms. Rusting and burning are chemical changes.","chemical change"),("Chemical changes are usually not reversible.","not reversible"),("Signs of a chemical change are a new colour, gas, smell or new solid.","signs of change")],
 ex=("Is the burning of a candle a physical or chemical change?",[("The wax melts, which is physical, but the burning makes new substances like gases.","New substances form."),("The flame gives heat and light, and the wax cannot be got back.","It is not reversible."),("So burning is a chemical change.","Melting alone would be physical.")]),
 tb=("A friend says dissolving sugar in water is a chemical change because the sugar disappears. How will you explain?",["No new substance forms; sugar can be got back by evaporating the water.","So it is a physical change."],["Thinking that disappearing means a new substance."]),
 summary=["Physical change: no new substance.","Chemical change: new substance forms, usually irreversible.","Rusting, burning and curdling are chemical changes."],
 q=[("mcq",1,"r1-melt","Melting of ice is a","physical change",[("chemical change","No new substance forms."),("nuclear change","Not relevant.")],"Water can freeze back to ice."),
    ("tf",1,"r1-rust","Rusting of iron is a chemical change.",True,"True."),
    ("mcq",2,"r2-new","In a chemical change","a new substance forms",[("nothing new forms","That is a physical change."),("the state only changes","That is a physical change.")],"New properties appear."),
    ("tf",2,"r2-cut","Cutting paper is a chemical change.",False,"False."),
    ("mcq",3,"r3-burn","Burning of paper is","a chemical change",[("a physical change","New substances such as ash and gases form."),("not a change","It is a change.")],"It cannot be reversed."),
    ("short",3,"r3-ex","Name one chemical change.",["rusting","burning","curdling of milk","cooking","digestion","baking","rotting","souring of milk"],"New substances form."),
    ("mcq",4,"r4-sign","Which is a sign of a chemical change?","a gas is given off",[("shape changes only","That may be physical."),("size changes only","That may be physical.")],"Bubbles may show a gas."),
    ("tf",4,"r4-rev","Physical changes can often be reversed.",True,"True.")]))
build(dict(S,ch="adolescence-a-stage-of-growth-and-change",topic="changes-during-adolescence",name_en="Changes during adolescence",name_ta="பதின்பருவ மாற்றங்கள்",
 objectives=["Say what adolescence is","Describe healthy habits during this stage"],
 story=("Growing up","Arjun noticed that he had grown taller this year and his voice sounded different. His sister Nila said she felt moody some days.\n\"These are normal changes,\" said their teacher. \"Everyone passes through adolescence.\""),
 explain=["Adolescence is the stage of life between childhood and adulthood, roughly between 10 and 19 years. Body and feelings change in this period.","Common changes include a rapid increase in height and weight, changes in the voice, growth of body hair and changes in the way we feel. These changes are controlled by chemical messengers called hormones, and they come at different ages for different people.","A balanced diet, enough sleep, exercise, cleanliness and talking to trusted adults help. Respect others and avoid harmful habits. Mood changes are normal and sharing feelings with family or teachers helps."],
 terms=["adolescence","puberty","hormones","balanced diet"],
 narr=[("Adolescence is the stage between childhood and adulthood, from about ten to nineteen years.","adolescence"),("The body grows quickly and the voice changes. Hormones control these changes.","body changes, hormones"),("Everyone changes at a different time. This is normal.","everyone is different"),("Eat well, sleep well, exercise, keep clean and talk to trusted adults.","healthy habits")],
 ex=("Why do some classmates grow taller earlier than others?",[("Hormones control the changes of adolescence.","They work at different times in each person."),("So growth starts earlier for some and later for others.","This is normal."),("There is no need to compare ourselves with others.","Everyone catches up in time.")]),
 tb=("A friend feels upset about mood swings. What will you tell him?",["Mood changes are normal in adolescence because of hormones.","Talking to a trusted adult or friend helps."],["Thinking mood changes mean something is wrong."]),
 summary=["Adolescence is the stage between childhood and adulthood.","Hormones control the body's changes.","Healthy habits and talking to trusted people help."],
 q=[("mcq",1,"r1-age","Adolescence is roughly the age of","10 to 19 years",[("1 to 5 years","That is early childhood."),("40 to 50 years","That is adulthood.")],"It is a stage of rapid change."),
    ("tf",1,"r1-hor","Hormones control many changes in adolescence.",True,"True."),
    ("mcq",2,"r2-voice","A common change in adolescence is","a change in the voice",[("losing all height","Height increases."),("stopping growth at once","Growth is fast.")],"The voice changes."),
    ("tf",2,"r2-same","All adolescents change at exactly the same age.",False,"False."),
    ("mcq",3,"r3-diet","A healthy habit in adolescence is","eating a balanced diet",[("skipping meals","That is unhealthy."),("sleeping very little","Sleep is needed.")],"The body needs good food."),
    ("short",3,"r3-habit","Name one healthy habit.",["exercise","sleep","balanced diet","cleanliness","eating well","playing","washing","good food","yoga"],"Exercise and sleep help."),
    ("mcq",4,"r4-mood","Mood changes in adolescence are","normal",[("always a disease","They are normal."),("a punishment","They are a natural part of growing.")],"Talking helps."),
    ("tf",4,"r4-talk","Sharing feelings with trusted adults is helpful.",True,"True.")]))
build(dict(S,ch="heat-transfer-in-nature",topic="conduction-convection-radiation",name_en="Conduction, convection and radiation",name_ta="கடத்தல், வெப்பச்சலனம், கதிர்வீச்சு",
 objectives=["Name the three ways heat travels","Match each with an example"],
 story=("The hot kitchen","Divya stirred hot dal with a steel spoon and the handle became hot. Above the pot she saw steam rising. Standing a little away she still felt warmth from the stove.\n\"Heat reaches me in three different ways!\" she said."),
 explain=["Conduction is the transfer of heat through a solid from the hot part to the colder part, without the material itself moving. A steel spoon heats up this way. Metals conduct well; wood and plastic do not.","Convection is the transfer of heat by the movement of a liquid or gas. Warm fluid rises and cooler fluid sinks, making a circulation. Boiling water and sea breezes are examples.","Radiation is the transfer of heat without any material, as waves. Heat from the Sun reaches the Earth by radiation. Dark surfaces absorb more heat and light surfaces reflect it."],
 terms=["conduction","convection","radiation","sea breeze"],
 narr=[("Conduction is heat travelling through a solid, like along a steel spoon.","conduction"),("Convection is heat carried by moving liquids or gases. Warm fluid rises, cool fluid sinks.","convection"),("Radiation is heat travelling as waves without any material. The Sun's heat reaches us this way.","radiation"),("Dark surfaces take in more heat. Light surfaces reflect it.","dark and light colours")],
 ex=("How does heat from the Sun reach the Earth through empty space?",[("Space has almost no matter, so conduction and convection cannot work.","They need a material."),("Radiation does not need a material.","It travels as waves."),("So the Sun's heat reaches us by radiation.","We feel it as warmth.")]),
 tb=("A friend says white clothes are worn in summer because they look nice. How will you explain?",["White reflects more heat and light and stays cooler.","Dark clothes absorb more heat."],["Missing the science behind colour choices."]),
 summary=["Conduction: through solids.","Convection: through moving liquids and gases.","Radiation: as waves, with no material needed."],
 q=[("mcq",1,"r1-cond","Heat travelling along a steel spoon is","conduction",[("convection","That is in fluids."),("radiation","That needs no material.")],"Heat moves through the solid."),
    ("tf",1,"r1-conv","Convection happens in liquids and gases.",True,"True."),
    ("mcq",2,"r2-sun","The Sun's heat reaches Earth by","radiation",[("conduction","There is no solid path."),("convection","Space has no fluid.")],"Waves cross empty space."),
    ("tf",2,"r2-dark","Dark surfaces absorb more heat than light surfaces.",True,"True."),
    ("mcq",3,"r3-rise","In convection, warm fluid","rises",[("sinks","Cool fluid sinks."),("stays still","It moves.")],"Warm fluid is lighter."),
    ("short",3,"r3-white","Why are white clothes cooler in summer?",["they reflect heat","reflect heat","reflect sunlight","reflect more heat","reflects heat"],"White reflects most heat."),
    ("mcq",4,"r4-breeze","A sea breeze is caused by","convection",[("conduction","It is air movement."),("magnetism","Not related.")],"Warm land air rises, cool sea air moves in."),
    ("tf",4,"r4-wood","Wood is a good conductor of heat.",False,"False.")]))
build(dict(S,ch="measurement-of-time-and-motion",topic="speed-and-time",name_en="Speed and time",name_ta="வேகமும் காலமும்",
 objectives=["Define speed and calculate it","Say how time was measured by clocks"],
 story=("The school bus","Ria's school bus travelled 30 kilometres in one hour. Her uncle's car did 60 kilometres in the same hour.\n\"Your uncle's car is faster,\" said the driver. \"It covers more distance in the same time.\""),
 explain=["Speed is the distance travelled in a unit of time. Speed = distance ÷ time. If a bus travels 60 km in 2 hours its speed is 30 km per hour. Units are metres per second (m/s) or kilometres per hour (km/h).","Time is measured using clocks. People once used sundials and water clocks, then pendulum clocks, and now quartz and digital clocks. A pendulum swings with a regular time period.","A body moving at the same speed all the time has uniform speed, while one that speeds up or slows down has non-uniform speed. A speedometer shows speed and an odometer shows distance covered."],
 terms=["speed","distance","time period","speedometer","uniform"],
 narr=[("Speed is the distance travelled in one unit of time. Speed equals distance divided by time.","speed = distance ÷ time"),("A bus that goes 60 kilometres in 2 hours has a speed of 30 kilometres per hour.","example"),("Clocks have changed from sundials to pendulum clocks to digital clocks.","clocks"),("A speedometer shows speed. An odometer shows the distance covered.","speedometer, odometer")],
 ex=("A train travels 180 km in 3 hours. What is its speed?",[("Speed equals distance divided by time.","Use the formula."),("180 divided by 3 is 60.","Do the division."),("So its speed is 60 kilometres per hour.","Write the unit.")]),
 tb=("A friend says a car that goes 100 km is always faster than one that goes 50 km. How will you explain?",["We must compare the times too.","50 km in 30 minutes is faster than 100 km in 4 hours."],["Judging speed by distance alone."]),
 summary=["Speed = distance ÷ time.","Units are m/s and km/h.","A speedometer shows speed and an odometer shows distance."],
 q=[("mcq",1,"r1-formula","Speed is","distance divided by time",[("time divided by distance","That is inverted."),("distance plus time","Wrong operation.")],"Speed shows how fast we move."),
    ("tf",1,"r1-unit","Kilometres per hour is a unit of speed.",True,"True."),
    ("mcq",2,"r2-calc","A cyclist covers 24 km in 2 hours. Speed?","12 km/h",[("48 km/h","That multiplies."),("26 km/h","That adds.")],"24 ÷ 2 = 12."),
    ("tf",2,"r2-odo","An odometer shows the distance covered.",True,"True."),
    ("mcq",3,"r3-clock","An old clock that used swinging was the","pendulum clock",[("digital clock","That is modern."),("sundial","A sundial uses shadows.")],"A pendulum has a regular time period."),
    ("short",3,"r3-device","Which instrument shows the speed of a vehicle?",["speedometer","speed-o-meter","a speedometer"],"The speedometer shows speed."),
    ("mcq",4,"r4-unif","Uniform speed means","same speed all the time",[("speeding up","That is non-uniform."),("stopping","That is rest.")],"Speed does not change."),
    ("tf",4,"r4-water","People once used water clocks.",True,"True.")]))
